package com.lexiscan.auth; import com.lexiscan.user.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepository users; public JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {var h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{var u=users.findById(jwt.subject(h.substring(7))).filter(User::isEnabled);if(u.isPresent()){var a=new UsernamePasswordAuthenticationToken(u.get(),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.get().getRole().name())));SecurityContextHolder.getContext().setAuthentication(a);}}catch(Exception ignored){} c.doFilter(r,s);}}
